export const MODEL_VERSION='2.1.0';
export const SCREENING=Object.freeze({ca:.1,re:10,originalCa:.01,originalRe:1});
export const defaults=Object.freeze({geometry:'t',drive:'flow',solveFor:'qd',targetDiameter:Math.cbrt(4e6/Math.PI),inletPc:7,inletPd:.65,junctionP:0,qc:6,qd:2,wc:100,wd:80,h:50,lc:10,ld:10,muc:5,mud:1,rhoc:950,rhod:1000,sigma:20,alpha:1,ffDref:80,ffRatioRef:1/6,ffExponent:1/3,ffQcRef:6});
export const limits={qc:[.000001,10000],qd:[.000001,10000],wc:[1,5000],wd:[1,5000],h:[1,5000],lc:[.01,1000],ld:[.01,1000],muc:[.001,10000],mud:[.001,10000],rhoc:[1,30000],rhod:[1,30000],sigma:[.001,200],alpha:[.1,10],ffDref:[1,5000],ffRatioRef:[.000001,1000],ffExponent:[.01,2],ffQcRef:[.000001,10000],targetDiameter:[.001,100000],inletPc:[0,10000],inletPd:[0,10000],junctionP:[0,10000]};
export const labels={qc:'Continuous-phase flow',qd:'Dispersed-phase flow',wc:'Main-channel width',wd:'Dispersed inlet width',h:'Channel depth',lc:'Continuous inlet length',ld:'Dispersed inlet length',muc:'Continuous viscosity',mud:'Dispersed viscosity',rhoc:'Continuous density',rhod:'Dispersed density',sigma:'Interfacial tension',alpha:'Geometry coefficient α',ffDref:'Reference equivalent diameter',ffRatioRef:'Reference flow ratio',ffExponent:'Flow-ratio exponent',ffQcRef:'Reference total continuous flow',targetDiameter:'Target equivalent diameter',inletPc:'Continuous inlet pressure',inletPd:'Dispersed inlet pressure',junctionP:'Junction backpressure'};
const addedKeys=['ffDref','ffRatioRef','ffExponent','ffQcRef','drive','solveFor','targetDiameter','inletPc','inletPd','junctionP'];
export function normalizeParams(p){const q={...p};for(const k of addedKeys)if(q[k]===undefined)q[k]=defaults[k];return q;}
export function inputIsActive(p,k){if(k.startsWith('ff')&&p.geometry!=='ff')return false;if(['inletPc','inletPd','junctionP'].includes(k))return p.drive==='pressure';if(k==='targetDiameter')return p.drive==='diameter';if(k==='qc'||k==='qd')return p.drive!=='pressure'&&!(p.drive==='diameter'&&p.solveFor===k);return true;}
// Fully developed Newtonian flow in a rigid rectangular channel; odd Fourier series to n=199.
export function resistance(mu,length,width,height){const a=Math.min(width,height),b=Math.max(width,height);let sum=0;for(let n=1;n<200;n+=2)sum+=Math.tanh(n*Math.PI*b/(2*a))/n**5;return 12*mu*length/(b*a**3*(1-192*a*sum/(Math.PI**5*b)));}
export function hydraulicResistances(p){const ff=p.geometry==='ff',w=p.wc*1e-6,h=p.h*1e-6;return {rc:resistance(p.muc*.001,p.lc*.001,ff?w/2:w,h)/(ff?2:1),rd:resistance(p.mud*.001,p.ld*.001,p.wd*1e-6,h)};}
export function resolveOperatingPoint(input){const p=normalizeParams(input),errors={};if(!['t','ff'].includes(p.geometry))errors.geometry='Choose a valid chip geometry.';if(!['flow','diameter','pressure'].includes(p.drive))errors.drive='Choose flow, target diameter or pressure input.';if(!['qc','qd'].includes(p.solveFor))errors.solveFor='Choose the phase flow to calculate.';for(const [k,[min,max]] of Object.entries(limits)){if(!inputIsActive(p,k))continue;if(typeof p[k]!=='number'||!Number.isFinite(p[k])||p[k]<min||p[k]>max)errors[k]=`${labels[k]} must be between ${min} and ${max}.`;}
if(Object.keys(errors).length)return {valid:false,errors};const {rc,rd}=hydraulicResistances(p);
if(p.drive==='pressure'){if(p.inletPc<=p.junctionP)errors.inletPc='Continuous inlet pressure must exceed junction backpressure.';if(p.inletPd<=p.junctionP)errors.inletPd='Dispersed inlet pressure must exceed junction backpressure.';if(Object.keys(errors).length)return {valid:false,errors};p.qc=(p.inletPc-p.junctionP)*1000/rc*60e9;p.qd=(p.inletPd-p.junctionP)*1000/rd*60e9;}
if(p.drive==='diameter'){let q;if(p.geometry==='t'){const minimum=Math.cbrt(6*p.wc*p.wc*p.h/Math.PI);q=(Math.PI*p.targetDiameter**3/(6*p.wc*p.wc*p.h)-1)/p.alpha;if(!(q>0))errors.targetDiameter=`This T-junction requires d_eq > ${minimum.toFixed(3)} µm for positive dispersed flow.`;}else q=p.ffRatioRef*(p.targetDiameter/p.ffDref)**(1/p.ffExponent);
if(!Number.isFinite(q)||q<=0)errors.targetDiameter=errors.targetDiameter||'The target diameter produces no finite positive flow ratio. Adjust the target or calibration.';
if(Object.keys(errors).length)return {valid:false,errors};if(p.solveFor==='qd')p.qd=p.qc*q;else p.qc=p.qd/q;}
for(const k of ['qc','qd']){const [min,max]=limits[k];if(!Number.isFinite(p[k])||p[k]<min||p[k]>max){const field=p.drive==='pressure'?(k==='qc'?'inletPc':'inletPd'):p.drive==='diameter'?'targetDiameter':k;errors[field]=`Calculated ${k==='qc'?'Qc':'Qd'} is outside ${min}–${max} µL/min. Adjust the operating inputs, geometry or fluid properties.`;}}
return Object.keys(errors).length?{valid:false,errors}:{valid:true,params:p,rc,rd};}
export function validate(p){const s=resolveOperatingPoint(p);return s.valid?{}:s.errors;}
export function calculate(input){const solved=resolveOperatingPoint(input);if(!solved.valid)return {valid:false,errors:solved.errors};const p=solved.params,qc=p.qc*1e-9/60,qd=p.qd*1e-9/60,w=p.wc*1e-6,wd=p.wd*1e-6,h=p.h*1e-6,mu=p.muc*.001,mud=p.mud*.001,uc=qc/(w*h),ud=qd/(wd*h),cw=p.geometry==='ff'?w/2:w,dh=2*cw*h/(cw+h),dhd=2*wd*h/(wd+h),ca=mu*uc/(p.sigma*.001),rec=p.rhoc*uc*dh/mu,red=p.rhod*ud*dhd/mud,ratio=qd/qc,reasons=[];
if(ca>=SCREENING.ca)reasons.push('Ca ≥ 0.1: outside the expanded application screening limit.');if(rec>=SCREENING.re||red>=SCREENING.re)reasons.push('Inlet Re ≥ 10: outside the expanded application screening limit.');if(p.geometry==='t'&&p.h>p.wc)reasons.push('Depth exceeds main width: outside this planar T-junction model.');if(p.geometry==='t'&&(p.wd>p.wc||p.wc/p.wd>4))reasons.push('Inlet width ratio is outside the T-junction range (1 ≤ wc/wd ≤ 4).');const eligible=reasons.length===0,extended=ca>=SCREENING.originalCa||rec>=SCREENING.originalRe||red>=SCREENING.originalRe,length=eligible&&p.geometry==='t'?p.wc*(1+p.alpha*ratio):null,diameter=eligible?(p.geometry==='ff'?p.ffDref*(ratio/p.ffRatioRef)**p.ffExponent:Math.cbrt(6*length*p.wc*p.h/Math.PI)):null,volume=eligible?(p.geometry==='ff'?Math.PI*diameter**3/6e6:length*p.wc*p.h/1e6):null,frequency=eligible?p.qd*1000/60/volume:null,pc=solved.rc*qc/1000,pd=solved.rd*qd/1000,warnings=[...reasons];
if(extended)warnings.push('Expanded-range extrapolation: the app now permits Ca < 0.1 and inlet Re < 10. This does not extend the validated range of the squeezing law or an empirical flow-focusing calibration. Verify the breakup regime and size experimentally.');
if(p.drive==='pressure')warnings.push('Pressure-driven inlet estimate: Q = (Pin − Pj)/R. Pj defaults to 0 kPa gauge and must represent the actual junction backpressure. Rigid, fully developed single-phase inlet losses only; downstream two-phase resistance, junction losses, capillary entry/pressure jumps, tubing and PDMS deformation are excluded.');
if(p.drive==='diameter')warnings.push('Inverse size design solves the same forward model for one unknown phase flow. Diameter means equivalent-volume sphere diameter, not T-junction axial length or confined transverse width. Matching a target algebraically is not experimental validation.');
if(p.geometry==='ff'){warnings.push('Reference-point power law. Default coefficients are illustrative, not measured. Geometry and fluid-property effects on size are not modeled. Inverse and pressure-derived estimates retain this limitation.');if(Math.abs(p.qc-p.ffQcRef)>1e-9)warnings.push('Qc differs from its reference: size is an empirical extrapolation.');warnings.push('Flow focusing: Qc is total flow in two equal-pressure symmetric continuous inlets. wc is their summed width and lc is one branch length. Each side carries Qc/2; its resistance is calculated using wc/2.');}
if(eligible&&p.geometry==='t'&&!extended)warnings.push('Original low-Ca screening passed. Confirm squeezing and preferential continuous-phase wall wetting experimentally.');if(ratio>2||ratio<.1)warnings.push('Extreme flow ratio: verify stable breakup experimentally.');return {valid:true,eligible,extended,params:p,qc:p.qc,qd:p.qd,ratio,total:p.qc+p.qd,fraction:p.qd/(p.qc+p.qd),uc:uc*1000,ud:ud*1000,dh:dh*1e6,ca,rec,red,viscosityRatio:p.mud/p.muc,pc,pd,rc:solved.rc,rd:solved.rd,length,volume,diameter,frequency,targetResidual:p.drive==='diameter'&&diameter!==null?diameter-p.targetDiameter:null,warnings,reasons};}
export const resultFor=calculate;
export function fmt(n,d=2){if(n===null||n===undefined||!Number.isFinite(n))return '—';if(n!==0&&(Math.abs(n)<.001||Math.abs(n)>=1e6))return n.toExponential(2);return n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});}
